using System;using System.Collections;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 // A composed, replaceable receipt scene. No rewards, RNG, save access or input blocking.
 public sealed class ForgeSequence:MonoBehaviour {
  public ItemPortrait[] Sources;public ItemPortrait Hero;public Text Title,Rarity,Improvement;public Image Shade,Impact;public Image[] Conduits;public Sprite[] ImpactFrames;public Sprite ChargeSprite;
  public IEnumerator Present(ItemInstance[] items,ItemInstance result,string language,string improvement,RectTransform destination,Action impact,int[] componentIds=null,double[] amounts=null,Sprite[] materials=null){
   bool fusion=items.Length>0;int count=fusion?items.Length:componentIds.Length;var sources=new System.Collections.Generic.List<ItemPortrait>(Sources);var conduits=new System.Collections.Generic.List<Image>(Conduits);while(sources.Count<count){sources.Add(Instantiate(Sources[0],transform));conduits.Add(Instantiate(Conduits[0],transform));}var tint=ItemPortrait.RarityColor(result.rarity);for(int i=0;i<sources.Count;i++){var source=sources[i];source.gameObject.SetActive(i<count);if(i>=count){conduits[i].color=Color.clear;continue;}source.Button.interactable=false;var r=(RectTransform)source.transform;r.sizeDelta=Vector2.one*(count<=3?94:64);r.anchoredPosition=count<=3?new Vector2((i-(count-1)*.5f)*104,80):new Vector2((i%4-1.5f)*78,100-(i/4)*72);source.ShowLevel=!fusion;if(fusion)source.Bind(items[i]);else{source.Bind(null);source.Frame.color=GameTheme.Accent;source.Art.gameObject.SetActive(true);source.Art.sprite=materials[componentIds[i]];source.Art.preserveAspect=true;source.Art.rectTransform.sizeDelta=Vector2.one*(count<=3?60:40);source.Caption.text="×"+amounts[componentIds[i]];}}
   Hero.ShowLevel=false;Hero.Bind(result);Hero.gameObject.SetActive(false);Title.text=SettingsRules.Text(language,"item:"+result.type);Rarity.text=SettingsRules.Text(language,"rarity:"+ItemBalance.Rarities[result.rarity]).ToUpperInvariant()+" · Lv. "+result.level;Rarity.color=tint;Improvement.text=improvement;Improvement.color=GameTheme.Enough;
   foreach(var graphic in GetComponentsInChildren<Graphic>(true))graphic.raycastTarget=false;var starts=new Vector2[count];for(int i=0;i<count;i++)starts[i]=((RectTransform)sources[i].transform).anchoredPosition;Impact.rectTransform.sizeDelta=Vector2.one*(fusion?144:106);var hero=(RectTransform)Hero.transform;Vector2 center=hero.anchoredPosition;bool struck=false;float time=0;
   while(time<2.02f){time+=Time.unscaledDeltaTime;Shade.color=new Color(.015f,.03f,.055f,Mathf.Min(.94f,time*7));float prepare=Mathf.Clamp01(time/.28f),move=Mathf.Clamp01((time-.28f)/.36f),accelerate=move*move*move;
    for(int i=0;i<count;i++){var r=(RectTransform)sources[i].transform;var away=(starts[i]-center).normalized;float anticipation=Mathf.Sin(prepare*Mathf.PI*.5f)*9*(1-accelerate);r.anchoredPosition=Vector2.Lerp(starts[i],center,accelerate)+away*anticipation;r.localEulerAngles=new Vector3(0,0,(i-1)*Mathf.Sin(prepare*Mathf.PI)*-5);sources[i].gameObject.SetActive(time<.65f);var conduit=conduits[i];conduit.sprite=ChargeSprite;conduit.rectTransform.anchoredPosition=Vector2.Lerp(starts[i],center,.65f);conduit.rectTransform.localEulerAngles=new Vector3(0,0,Mathf.Atan2(center.y-starts[i].y,center.x-starts[i].x)*Mathf.Rad2Deg);conduit.color=new Color(tint.r,tint.g,tint.b,time<.64f?prepare*.8f:0);}
    if(time>=.64f&&!struck){struck=true;impact?.Invoke();}float hit=(time-.64f)/.3f;Impact.gameObject.SetActive(hit>=0&&hit<1);if(hit>=0&&hit<1){Impact.sprite=ImpactFrames[Mathf.Min(ImpactFrames.Length-1,(int)(hit*ImpactFrames.Length))];Impact.color=Color.Lerp(Color.white,tint,hit);}
    bool reveal=time>=.76f;Hero.gameObject.SetActive(reveal);float settle=Mathf.Clamp01((time-.76f)/.18f);hero.anchoredPosition=center+Vector2.down*(1-Mathf.Sin(settle*Mathf.PI*.5f))*16;Hero.Art.canvasRenderer.SetAlpha(settle);Title.canvasRenderer.SetAlpha(settle);Rarity.canvasRenderer.SetAlpha(settle);Improvement.canvasRenderer.SetAlpha(Mathf.Clamp01((time-.9f)/.12f));
    if(time>1.62f){float exit=Mathf.Clamp01((time-1.62f)/.4f),p=exit*exit;Vector2 end=((RectTransform)transform).InverseTransformPoint(destination.position);hero.anchoredPosition=Vector2.Lerp(center,end,p);hero.sizeDelta=Vector2.Lerp(new Vector2(176,176),new Vector2(52,52),p);Title.canvasRenderer.SetAlpha(1-exit);Rarity.canvasRenderer.SetAlpha(1-exit);Improvement.canvasRenderer.SetAlpha(1-exit);Shade.color=new Color(.015f,.03f,.055f,.94f*(1-exit));}
    yield return null;
   }
   PixelImpact.Play(destination,"StoredItemReceipt",Vector2.zero,fusion?72:46,tint,.18f);
  }
 }
}
